// MSD Deal Event — Validate + Normalize + Hash
const crypto = require('crypto');

const expectedSecret = '1a8847cc503b42b7cd27d6dbfab74f60b10abfa1b3e78f6ba414b9e4e76df3a8';

const raw = $input.first().json;
const body = raw.body || raw;
const headers = (raw.headers || {});

// Accept secret en body._secret O en header x-msd-deal-secret (HubSpot Workflows pueden mandar header)
const providedSecret = body._secret || headers['x-msd-deal-secret'] || headers['X-MSD-Deal-Secret'];
if (providedSecret !== expectedSecret) {
  throw new Error('Invalid secret');
}

const event = (body.event || '').toLowerCase();
if (!['deal_created', 'deal_won', 'deal_lost'].includes(event)) {
  throw new Error('Unknown event: ' + event);
}
const hs_deal_event = event.replace('deal_', ''); // 'created' | 'won' | 'lost'

const hs_deal_id = String(body.hs_deal_id || '').trim();
if (!hs_deal_id) throw new Error('Missing hs_deal_id');

const contact = body.primary_contact || {};
const normalizeEmail = (e) => (e || '').toLowerCase().trim();
const normalizePhone = (p) => (p || '').replace(/[^0-9+]/g, '');
const sha256 = (s) => crypto.createHash('sha256').update(s).digest('hex');

const email = normalizeEmail(contact.email);
const phone = normalizePhone(contact.phone);
const email_hash = email ? sha256(email) : null;
const phone_hash = phone ? sha256(phone) : null;

const amount = body.amount != null ? Number(body.amount) : null;
const hs_location = (body.msd_location || (body.primary_contact && body.primary_contact.location) || '').toLowerCase().trim();

return [{
  json: {
    hs_deal_id,
    hs_deal_event,
    hs_pipeline: body.pipeline || null,
    hs_dealstage: body.dealstage || null,
    hs_lead_source: body.lead_source || null,
    email_hash,
    phone_hash,
    amount,
    hs_location,
    closedate: body.closedate || null,
    createdate: body.createdate || null,
    raw_payload: body
  }
}];

// MSD Deal Event — Build conversion_upload_log row (Opcion E: Enhanced Conversions for Leads por email)
const items = $input.all();
const input = items[0].json;
const prev = $('Validate + Normalize').first().json;

const lead_id = input.lead_id || null;
const location_id = input.location_id || null;
const customer_id = input.google_ads_customer_id || null;

// Identificadores del DEAL mismo (server-side, no requiere captura client-side ni tocar el form)
const email_hash = prev.email_hash || null;
const phone_hash = prev.phone_hash || null;
const hasIdent = !!(email_hash || phone_hash);

// Pick conv_action_id according to event
const event = prev.hs_deal_event; // 'created' | 'won' | 'lost'
let conv_action_id = null;
let conv_action_name = null;
if (event === 'created') {
  conv_action_id = input.conv_action_id_deal_created || null;
  conv_action_name = 'HS Deal Created';
} else if (event === 'won') {
  conv_action_id = input.conv_action_id_deal_won || null;
  conv_action_name = 'HS Deal Won';
}

// match_method
let match_method = 'no_match';
if (!location_id) {
  match_method = 'no_location';
} else if (lead_id && input.gclid) {
  match_method = 'gclid+enhanced';
} else if (lead_id && input.gbraid) {
  match_method = 'gbraid';
} else if (lead_id && input.wbraid) {
  match_method = 'wbraid';
} else if (hasIdent) {
  match_method = 'enhanced_only'; // Opcion E: email del deal
}

// upload_status — encola si hay location + conv_action + algun identificador
let upload_status;
if (!location_id || !conv_action_id) {
  upload_status = 'dropped_no_location';
} else if (event === 'lost') {
  upload_status = 'dropped_no_match_try_match';
} else if (lead_id || hasIdent) {
  upload_status = 'queued_retry';
} else {
  upload_status = 'dropped_no_match_try_match';
}

// Conversion value
let conversion_value = null;
if (event === 'won' && prev.amount != null) conversion_value = prev.amount;
else if (event === 'created') conversion_value = 200.00;

// Conversion date_time: closedate (won) / createdate (created)
let conv_dt = null;
if (event === 'won') conv_dt = prev.closedate || new Date().toISOString();
else if (event === 'created') conv_dt = prev.createdate || new Date().toISOString();
else conv_dt = new Date().toISOString();

// identificadores para el uploader (Fase B los lee de api_request.identifiers)
const api_request = hasIdent
  ? JSON.stringify({ identifiers: { email_hash, phone_hash } })
  : null;

return [{
  json: {
    hs_deal_id: prev.hs_deal_id,
    hs_deal_event: event,
    hs_pipeline: prev.hs_pipeline,
    hs_dealstage: prev.hs_dealstage,
    hs_lead_source: prev.hs_lead_source,
    google_ads_customer_id: customer_id,
    google_ads_conversion_action_id: conv_action_id,
    google_ads_conversion_action_name: conv_action_name,
    location_id: location_id,
    matched_lead_id: lead_id,
    match_method: match_method,
    attribution_age_hours: input.age_hours ? Math.round(input.age_hours) : null,
    conversion_value: conversion_value,
    currency: 'USD',
    conversion_date_time: conv_dt,
    upload_status: upload_status,
    api_request: api_request,
    api_response: null,
    error_message: null,
    raw_payload: prev.raw_payload
  }
}];
